pub assume_specification<T, E>[ Result::<T, E>::as_mut ](
    result: &mut Result<T, E>,
) -> (res: Result<&mut T, &mut E>)
    ensures
        (match *old(result) {
            Result::Ok(value) => {
                &&& *final(result) is Ok
                &&& res is Ok
                &&& *(res->Ok_0) == value
                &&& *final(res->Ok_0) == (*final(result))->Ok_0
            },
            Result::Err(error) => {
                &&& *final(result) is Err
                &&& res is Err
                &&& *(res->Err_0) == error
                &&& *final(res->Err_0) == (*final(result))->Err_0
            },
        }),
    no_unwind
;

